    position: relative;
    width: 1024px;
    height: 576px;
    margin: 0 auto;
    background: linear-gradient(135deg, #16324f 0%, #1b3a5c 40%, #24455f 70%, #16324f 100%);
    overflow: hidden;
  }
  .content-box {
    position: absolute;
    top: 28px;
    left: 60px;
