  .title {
    text-align: center;
    color: #cc0000;
    font-size: 32px;
    font-weight: bold;
    margin: 12px 0 6px 0;
  }
  .intro {
    font-size: 15px;
    color: #111;
    margin: 0 30px 10px 30px;
    line-height: 1.35;
  }
  .subheading {
    font-size: 18px;
    font-weight: bold;
    color: #1b3a8f;
    margin: 14px 0 8px 50px;
  }
  .layout-row {
    display: flex;
    align-items: flex-start;
    margin-left: 50px;
  }
  table.mac-table {
    border-collapse: collapse;
    width: 460px;
  }
  table.mac-table th {
