    margin-left: 30px;
    width: 340px;
    font-size: 17px;
    color: #444444;
    line-height: 1.4;
  }
  .approx-note {
    margin-top: 18px;
    text-align: center;
    font-size: 17px;
    color: #444444;
    line-height: 1.4;
  }
  .footer-logos {
    position: absolute;
    bottom: 30px;
    left: 30px;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .placeholder {
    display: flex;
    align-items: center;
